-- New leaders copy the civilization fields of their source leader's row.
INSERT INTO Players (Domain, CivilizationType, LeaderType, LeaderName, LeaderIcon,
	CivilizationName, CivilizationIcon, LeaderAbilityName, LeaderAbilityDescription,
	LeaderAbilityIcon, CivilizationAbilityName, CivilizationAbilityDescription,
	CivilizationAbilityIcon, PortraitBackground)
SELECT b.Domain, p.CivilizationType, p.LeaderType, 'LOC_' || p.LeaderType || '_NAME',
	'ICON_' || p.LeaderType, b.CivilizationName, b.CivilizationIcon,
	'LOC_' || p.TraitType || '_NAME', 'LOC_' || p.LeaderType || '_PROFILE', 'ICON_LEADER_DEFAULT',
	b.CivilizationAbilityName, b.CivilizationAbilityDescription, b.CivilizationAbilityIcon,
	p.Background
FROM JAC_BanseikiPool p
JOIN Players b ON b.Domain = 'Players:Expansion2_Players'
	AND b.CivilizationType = p.CivilizationType AND b.LeaderType = p.SourceLeaderType
WHERE p.IsNew = 1
ORDER BY p.SortIndex;

-- Standard Gathering Storm and every other ruleset keep their leader list unchanged.
INSERT INTO Queries (QueryId, SQL) VALUES ('JAC_BanseikiPool_OtherRulesetFilter',
	'SELECT ''Players:Expansion2_Players'' AS Domain, LeaderType AS Value, ''difference'' AS Filter FROM JAC_BanseikiPool WHERE IsNew = 1 AND ?1 IS NOT ''RULESET_JAC_BANSEIKI''');
INSERT INTO QueryParameters (QueryId, "Index", ConfigurationGroup, ConfigurationId) VALUES
	('JAC_BanseikiPool_OtherRulesetFilter', 1, 'Game', 'RULESET');
INSERT INTO DomainValueFilterQueries (QueryId) VALUES ('JAC_BanseikiPool_OtherRulesetFilter');
